/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, CRootOf, Float, GeneratorsNeeded, I, Lambda, Mul, NotImplementedError, Poly, PolynomialError, Pow, Relational, RootSumNode, Sym, add, diff, doit, epsilonEq, exp, fn, isAlgebraic, isComplex, isImaginary, isReal, isUnsolved, log, mul, pow, pprintUseUnicode, rational, rootof, symbols } from '../../src';
import { at, pyLen, pyStr, sympyStr } from '../sympy-str';

describe("doctests of sympy.polys.rootoftools", () => {
  it("CRootOf.clear_cache()  # for doctest reproducibility", () => {
    CRootOf.clearCache();
    expect(sympyStr(CRootOf.clearCache())).toBe('None');
  });
  it("CRootOf(x**2 - 4, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(CRootOf(add(-4, pow(x, 2)), rational(0)))).toBe('-2');
  });
  it("CRootOf(x**2 - 3, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(CRootOf(add(-3, pow(x, 2)), rational(0)))).toBe('CRootOf(x**2 - 3, 0)');
  });
  it("CRootOf(x**2 - 3, 0, radicals=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(CRootOf(add(-3, pow(x, 2)), rational(0), { radicals: true }))).toBe('-sqrt(3)');
  });
  it("rootof(x**2 - 3, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(rootof(add(-3, pow(x, 2)), rational(0)))).toBe('-sqrt(3)');
  });
  it("r.evalf(2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new CRootOf(add(7, mul(4, pow(x, 5)), mul(12, pow(x, 2)), mul(16, pow(x, 3))), 0).evalf(2, {}))).toBe('-0.98');
  });
  it("r.eval_approx(2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new CRootOf(add(7, mul(4, pow(x, 5)), mul(12, pow(x, 2)), mul(16, pow(x, 3))), 0).evalApprox(rational(2)))).toBe('-0.98');
  });
  it("r.eval_rational(n=2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new CRootOf(add(7, mul(4, pow(x, 5)), mul(12, pow(x, 2)), mul(16, pow(x, 3))), 0).evalRational(undefined, undefined, { n: rational(2) }))).toBe('-69629/71318');
  });
  it("t.eval_rational(1e-1)", () => {
    const x = new Sym('x');
    expect(sympyStr(new CRootOf(add(1, pow(x, 3), mul(10, x)), 1).evalRational(new Float(0.1)))).toBe('15/256 - 805*I/256');
  });
  it("t.eval_rational(1e-1, 1e-4)", () => {
    const x = new Sym('x');
    expect(sympyStr(new CRootOf(add(1, pow(x, 3), mul(10, x)), 1).evalRational(new Float(0.1), new Float(0.0001)))).toBe('3275/65536 - 414645*I/131072');
  });
  it("t.eval_rational(1e-4, 1e-4)", () => {
    const x = new Sym('x');
    expect(sympyStr(new CRootOf(add(1, pow(x, 3), mul(10, x)), 1).evalRational(new Float(0.0001), new Float(0.0001)))).toBe('6545/131072 - 414645*I/131072');
  });
  it("t.eval_rational(n=2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new CRootOf(add(1, pow(x, 3), mul(10, x)), 1).evalRational(undefined, undefined, { n: rational(2) }))).toBe('104755/2097152 - 6634255*I/2097152');
  });
  it("PurePoly(x) == PurePoly(exp(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(Poly.from(x, [x], { domain: 'ZZ', pure: true }).equals(Poly.from(exp(x), [exp(x)], { domain: 'ZZ', pure: true })))).toBe('True');
  });
  it("CRootOf(x - 1, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(CRootOf(add(-1, x), rational(0)))).toBe('1');
  });
  it("r.eval_rational(10**-8).n(6)", () => {
    expect(sympyStr(rational(368345497, 427743544).evalf(6, {}))).toBe('0.861136');
  });
  it("r.evalf(17)", () => {
    const x = new Sym('x');
    expect(sympyStr(new CRootOf(add(3, mul(-30, pow(x, 2)), mul(35, pow(x, 4))), 3).evalf(17, {}))).toBe('0.86113631159405258');
  });
  it("P[y]", () => {
    expect(sympyStr(rational(1))).toBe('1');
  });
  it("x + 1 in P", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
});

